#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <Adafruit_BME280.h>

const int BTN_PIN = D1;
const int OLED_W = 128;
const int OLED_H = 64;
Adafruit_SSD1306 display(OLED_W, OLED_H, &Wire, -1);
Adafruit_BME280 bme;
bool hasBme = false;
bool hasDisplay = false;
int page = 0;
const int PAGES = 3;
int lastBtn = HIGH;
unsigned long lastDeb = 0;
unsigned long lastRead = 0;
float t = 21.5;
float h = 45.0;
float p = 1013.0;

void showPage() {
  if (!hasDisplay) return;
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  if (page == 0) {
    display.setTextSize(1);
    display.setCursor(0, 0);
    display.println("Meteo");
    display.setTextSize(2);
    display.setCursor(0, 16);
    display.print(t, 1);
    display.println(" C");
    display.setTextSize(1);
    display.setCursor(0, 40);
    display.print(h, 0);
    display.println(" %");
    display.setCursor(0, 52);
    display.print(p, 0);
    display.println(" hPa");
  } else if (page == 1) {
    display.setTextSize(1);
    display.setCursor(0, 0);
    display.println("Humidity / Press");
    display.setTextSize(2);
    display.setCursor(0, 18);
    display.print(h, 0);
    display.println(" %");
    display.setCursor(0, 42);
    display.print(p, 0);
    display.println(" hPa");
  } else {
    display.setTextSize(1);
    display.setCursor(0, 0);
    display.println("Temperature");
    display.setTextSize(3);
    display.setCursor(0, 20);
    display.print(t, 1);
    display.setTextSize(2);
    display.print(" C");
  }
  display.display();
}

void setup() {
  pinMode(BTN_PIN, INPUT_PULLUP);
  Wire.begin();
  hasDisplay = display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  if (hasDisplay) {
    display.clearDisplay();
    display.display();
  }
  hasBme = bme.begin(0x76);
  if (!hasBme) hasBme = bme.begin(0x77);
  showPage();
}

void loop() {
  int b = digitalRead(BTN_PIN);
  if (b != lastBtn) {
    lastDeb = millis();
    lastBtn = b;
  }
  static int stable = HIGH;
  if ((millis() - lastDeb) > 30) {
    if (stable != lastBtn) {
      stable = lastBtn;
      if (stable == LOW) {
        page = (page + 1) % PAGES;
        showPage();
      }
    }
  }
  if (millis() - lastRead > 2000) {
    lastRead = millis();
    if (hasBme) {
      t = bme.readTemperature();
      h = bme.readHumidity();
      p = bme.readPressure() / 100.0;
    }
    showPage();
  }
}

